// Runnable demo. In a real project each class lives in its own file.
package com.bank.ingest;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ExchangerDemo {
    private static final Logger LOG = Logger.getLogger("Ingest");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Exchanger<List<Trade>> ex = new Exchanger<>();
        Ledger ledger = new Ledger(LOG);

        List<Trade> incoming = List.of(
            new Trade("T1", "SAV2001", new BigDecimal("50000")),
            new Trade("T2", "CUR3001", new BigDecimal("30000")),
            new Trade("T3", "SAV2001", new BigDecimal("20000")),
            new Trade("T4", "CUR3001", new BigDecimal("10000")));

        Thread reader = new Thread(new TradeReader(ex, incoming, 2, LOG), "reader");
        Thread writer = new Thread(new LedgerWriter(ex, ledger, 2, LOG), "writer");
        reader.start();
        writer.start();
        reader.join();
        writer.join();

        LOG.info(() -> "Posted total trades = " + ledger.postedCount());
    }
}

// ─── Would be in model/Trade.java ───
record Trade(String id, String accountId, BigDecimal amount) {}

// ─── Would be in ledger/Ledger.java ───
class Ledger {
    private final Logger log;
    private int posted = 0;
    Ledger(Logger log) { this.log = log; }
    synchronized void post(Trade t) {
        posted++;
        log.info(() -> "Posted " + t.id() + " amount Rs." + t.amount() + " to " + t.accountId());
    }
    synchronized int postedCount() { return posted; }
}

// ─── Would be in io/TradeReader.java ───
class TradeReader implements Runnable {
    private final Exchanger<List<Trade>> ex;
    private final List<Trade> source;
    private final int capacity;
    private final Logger log;
    TradeReader(Exchanger<List<Trade>> ex, List<Trade> source, int capacity, Logger log) {
        this.ex = ex; this.source = source; this.capacity = capacity; this.log = log;
    }
    @Override public void run() {
        List<Trade> buffer = new ArrayList<>();   // buffer A
        try {
            for (Trade t : source) {
                buffer.add(t);
                if (buffer.size() == capacity) {
                    log.info(() -> "reader: buffer full, swapping");
                    buffer = ex.exchange(buffer);  // hand full, receive empty buffer B
                    buffer.clear();
                }
            }
            // final partial batch: swap with a sentinel-aware writer loop end
            ex.exchange(buffer);                   // hand remaining trades
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

// ─── Would be in io/LedgerWriter.java ───
class LedgerWriter implements Runnable {
    private final Exchanger<List<Trade>> ex;
    private final Ledger ledger;
    private final int expectedSwaps;
    private final Logger log;
    LedgerWriter(Exchanger<List<Trade>> ex, Ledger ledger, int expectedSwaps, Logger log) {
        this.ex = ex; this.ledger = ledger; this.expectedSwaps = expectedSwaps; this.log = log;
    }
    @Override public void run() {
        List<Trade> buffer = new ArrayList<>();    // buffer B
        try {
            for (int i = 0; i <= expectedSwaps; i++) {
                buffer = ex.exchange(buffer, 3, TimeUnit.SECONDS); // hand empty, receive full
                log.info(() -> "writer: received " + buffer.size() + " trades");
                buffer.forEach(ledger::post);
                buffer.clear();
            }
        } catch (InterruptedException | TimeoutException e) {
            log.severe("writer: no partner arrived, raising alert");
        }
    }
}
