package com.bank.ingest.io;

import org.junit.jupiter.api.Test;
import java.util.concurrent.Exchanger;
import static org.junit.jupiter.api.Assertions.*;

class ExchangerSwapTest {
    @Test
    void twoThreadsSwapObjects() throws Exception {
        Exchanger<String> ex = new Exchanger<>();
        String[] got = new String[2];
        Thread a = new Thread(() -> { try { got[0] = ex.exchange("A"); } catch (Exception ignored) {} });
        Thread b = new Thread(() -> { try { got[1] = ex.exchange("B"); } catch (Exception ignored) {} });
        a.start(); b.start(); a.join(); b.join();
        assertEquals("B", got[0]);   // A received B's object
        assertEquals("A", got[1]);   // B received A's object
    }
}
